<?php
namespace App\Services\DevOps;use App\Models\ZigoHealthCheck;
final class PlatformStatusService {private const MAP=['landing_b2c'=>'home','postal_lookup_64000'=>'postal_lookup','colonias_64000'=>'colonias','crm'=>'crm_login','b2b'=>'negocios_login','soporte'=>'soporte_login','api_hub'=>'api_hub','devops'=>'devops'];public function current(string $environment):array{$out=[];foreach(self::MAP as $label=>$key){$check=ZigoHealthCheck::where('environment',$environment)->where('check_key',$key)->latest('checked_at')->first();$out[$label]=['status'=>$this->normalize($check?->status),'last_checked_at'=>$check?->checked_at,'duration_ms'=>$check?->duration_ms,'message'=>$check?->message??'Sin resultado persistido.'];}return$out;}private function normalize(?string $status):string{return match($status){'success'=>'up','warning'=>'warning','failed'=>'down','skipped'=>'skipped',default=>'unknown'};}}
